-- Beehive compliance library: official documents behind each checklist item,
-- with a plain-English summary and steps to comply. Reference data shared by all centres.
-- Generated by tools/compliance_library.py (sources checked 2026-10-25). Edit that file, not this one.

create table if not exists public.compliance_guides (
  item_key     text primary key,
  area         public.checklist_area not null,
  title        text not null,
  source_ref   text not null,
  summary      text not null,
  directions   text[] not null default '{}',
  evidence     text not null default '',
  retention    text not null default '',
  sort         int not null default 0,
  checked_on   date not null
);

create table if not exists public.compliance_documents (
  id           uuid primary key default gen_random_uuid(),
  item_key     text references public.compliance_guides (item_key) on delete cascade,  -- null = general reference
  title        text not null,
  issuer       text not null,
  doc_type     text not null,
  jurisdiction text not null default 'National',
  published    text not null default '',
  url          text not null check (url like 'https://%'),
  note         text not null default '',
  sort         int not null default 0,
  checked_on   date not null
);
create index if not exists compliance_documents_item_idx on public.compliance_documents (item_key, sort);

alter table public.compliance_guides enable row level security;
alter table public.compliance_documents enable row level security;
drop policy if exists "signed-in users read guides" on public.compliance_guides;
create policy "signed-in users read guides" on public.compliance_guides for select to authenticated using (true);
drop policy if exists "signed-in users read documents" on public.compliance_documents;
create policy "signed-in users read documents" on public.compliance_documents for select to authenticated using (true);
grant select on public.compliance_guides, public.compliance_documents to authenticated;

-- Re-runnable: replace the library contents.
delete from public.compliance_documents;
delete from public.compliance_guides;

insert into public.compliance_guides (item_key, area, title, source_ref, summary, directions, evidence, retention, sort, checked_on) values
  ('wwcc', 'staff_records', 'Current WWCC register', 'National Regulations · Reg. 145–147 · NSW WWCC',
   'Everyone working or volunteering with children needs a current Working With Children Check. The staff record must hold each person''s WWCC number and expiry date, and in NSW the employer must verify every Check online and record the result.',
   array['Before someone starts, verify their WWCC clearance number online with the Office of the Children''s Guardian. Education workers need a clearance number, not only an application number.', 'Record each person''s full name, date of birth, WWCC number, verification date and outcome, expiry date, and whether the role is paid or voluntary.', 'Verify again online whenever a Check is renewed. Checks last 5 years and can be renewed up to 3 months before expiry.', 'Remove anyone whose Check is barred, interim barred, not found or expired from child-related work straight away.', 'Have a second authorised person verify the verifier''s own Check. Nobody can verify their own.']::text[],
   'Staff record with a WWCC number, expiry date and online verification date for every staff member, volunteer and student.', 'Staff records: 3 years after the person stops working at the service (Reg. 183).', 1, '2026-10-25');
insert into public.compliance_guides (item_key, area, title, source_ref, summary, directions, evidence, retention, sort, checked_on) values
  ('firstaid', 'staff_records', 'First Aid and CPR evidence', 'National Regulations · Reg. 136',
   'At all times children are present, at least one staff member with a current approved first aid qualification, one with approved anaphylaxis management training and one with approved emergency asthma management training must be on site and immediately available. One person can hold all three.',
   array['Check each certificate against ACECQA''s approved first aid qualifications list, using the course code on the certificate.', 'Roster so someone holding each of the three qualifications is on site for every hour you''re open, including early, late and excursion shifts.', 'Track expiry dates. Industry practice is to renew first aid, anaphylaxis and asthma training every 3 years and CPR every 12 months. Check each certificate for its own renewal requirement.', 'Keep a copy of every certificate on the staff record.']::text[],
   'Current certificates on staff records, and rosters showing qualified staff on site at all times.', 'Staff records: 3 years after the person stops working at the service (Reg. 183).', 2, '2026-10-25');
insert into public.compliance_guides (item_key, area, title, source_ref, summary, directions, evidence, retention, sort, checked_on) values
  ('training', 'staff_records', 'Staff qualification and training records', 'National Regulations · Reg. 84, 145–147 · National Law s162A',
   'Staff records must show each person''s qualifications and approved training. Everyone working with children must keep up to date with child protection law and their mandatory reporting duties. In NSW, nominated supervisors and persons in day-to-day charge need approved child protection training, and everyone working at a service needs national child safety training.',
   array['Keep a copy of each person''s qualification, or proof of enrolment in an approved course, plus their other approved training, on the staff record.', 'Make sure nominated supervisors and persons in day-to-day charge have completed approved child protection training (CHCPRT025 or CHCPRT026). In-house training doesn''t count.', 'Have every new worker complete national child safety training within 14 days of starting, or before working directly with children if that''s sooner, and refresh it every 2 years.', 'Brief staff on child protection law and how to make a report. Nominated supervisors must be able to explain these obligations (Reg. 84).', 'Check qualifications against ACECQA''s approved qualifications list.']::text[],
   'Staff records with copies of qualifications and training, and a register of child protection and child safety training dates.', 'Staff records: 3 years after the person stops working at the service (Reg. 183).', 3, '2026-10-25');
insert into public.compliance_guides (item_key, area, title, source_ref, summary, directions, evidence, retention, sort, checked_on) values
  ('enrolment', 'childrens_records', 'Children’s enrolment and contact records', 'National Regulations · Reg. 160–162',
   'Keep an enrolment record for every child with their details, each parent''s contacts, an emergency contact, authorised nominees, people who can consent to medical treatment, outings or transport, any court or parenting orders, and health information including their doctor.',
   array['Use a complete enrolment form (ACECQA has a template). Don''t leave fields blank: write "not provided" and note what the service will do.', 'Record contacts for each parent, an emergency contact for when no parent can be reached, authorised nominees, and anyone who can consent to medical treatment, outings or transport.', 'Record the child''s doctor and any health need, allergy or medical condition (Reg. 162).', 'Keep copies of any court orders, parenting orders or parenting plans you''ve been given.', 'Check immunisation documents meet NSW requirements before the child starts.', 'Review contacts, authorised people and medical details with each family at least every 12 months, and whenever things change.']::text[],
   'A complete enrolment record for every child, with the date it was last reviewed.', 'Child records: 3 years after the child''s last day at the service (Reg. 183).', 4, '2026-10-25');
insert into public.compliance_guides (item_key, area, title, source_ref, summary, directions, evidence, retention, sort, checked_on) values
  ('incidents', 'childrens_records', 'Incident, injury, trauma and illness records', 'National Regulations · Reg. 85–87, 176 · National Law s174',
   'Have incident, injury, trauma and illness procedures. Record each incident as soon as possible and within 24 hours, tell the parent as soon as practicable and within 24 hours, and notify the regulator of any serious incident within 24 hours.',
   array['Complete the incident record as soon as possible and within 24 hours, including what happened, the action taken and who was told.', 'Tell the parent or carer as soon as practicable, and no later than 24 hours after the incident.', 'For a serious incident, notify the NSW Early Learning Commission through the NQA IT System within 24 hours.', 'Store records confidentially.', 'Review incidents regularly for patterns and update your risk assessments.']::text[],
   'Incident records showing when the parent was told, and NQA IT System receipts for serious incidents.', 'Incident, injury, trauma and illness records: until the child turns 25 (Reg. 183).', 5, '2026-10-25');
insert into public.compliance_guides (item_key, area, title, source_ref, summary, directions, evidence, retention, sort, checked_on) values
  ('medical', 'childrens_records', 'Medical management and risk minimisation records', 'National Regulations · Reg. 90–96, 162',
   'Have a medical conditions policy, even if no child currently has a condition. For each child with a diagnosed condition such as asthma, diabetes or anaphylaxis risk, keep a medical management plan from the parent, a risk minimisation plan and a communication plan. Give parents the policy and record any medication given.',
   array['Ask about health needs, allergies and medical conditions at enrolment and again when the child starts.', 'Get the child''s medical management plan (for example an ASCIA action plan) from the family before the child attends.', 'Write a risk minimisation plan and a communication plan with the family. ACECQA has a template.', 'Give the family a copy of your medical conditions policy.', 'Brief all staff, including casuals, volunteers and students, and show them where each child''s medication is kept.', 'Check medication expiry dates regularly, and review plans with the family when the child''s needs change.']::text[],
   'Medical management, risk minimisation and communication plans on each child''s record, plus medication records.', 'Child records, including medication records: 3 years after the child''s last day at the service (Reg. 183).', 6, '2026-10-25');
insert into public.compliance_guides (item_key, area, title, source_ref, summary, directions, evidence, retention, sort, checked_on) values
  ('authorisations', 'childrens_records', 'Authorisations and child collection records', 'National Regulations · Reg. 99, 102, 158, 161',
   'A child may only leave with a parent, an authorised nominee named in their enrolment record, or someone a parent or nominee has authorised. Otherwise it must be with written authorisation, for an excursion or service transport, or because of a medical emergency. Record each arrival and departure with the signature of the person dropping off or collecting.',
   array['Keep each child''s authorised nominees, with contact details, in their enrolment record.', 'Check the identity of anyone staff don''t know before handing over a child, for example with photo ID.', 'Have the attendance record signed at every drop-off and pick-up, with the date and time.', 'Get written authorisation for excursions and regular outings. Authorisations for regular outings must be renewed at least every 12 months.', 'Have a procedure for when an unauthorised or unfit person tries to collect a child, and for children who aren''t collected.', 'Do a final check at closing so no child is left on the premises.']::text[],
   'Signed attendance records, authorisations in enrolment records, and excursion permissions.', 'Child records, including attendance: 3 years after the child''s last day at the service (Reg. 183).', 7, '2026-10-25');
insert into public.compliance_guides (item_key, area, title, source_ref, summary, directions, evidence, retention, sort, checked_on) values
  ('evacuation', 'safety_premises', 'Emergency evacuation drill logged this quarter', 'National Regulations · Reg. 97, 98',
   'Have emergency and evacuation procedures based on a risk assessment of the emergencies that could affect your service. Rehearse every procedure (for example evacuation and lockdown) every 3 months and record each rehearsal.',
   array['Do a risk assessment of the emergencies that could affect your service, and review it at least every 12 months.', 'Rehearse each procedure every 3 months. Vary the day and time so every child and staff member takes part over the year.', 'Record each rehearsal: date, time, which procedure, who took part, how long it took and what to improve. The nominated supervisor keeps these records.', 'Display the evacuation floor plan and instructions in a prominent position near each exit.', 'Make sure staff can always reach a phone or other way to call for help (Reg. 98).']::text[],
   'A rehearsal record dated within the last 3 months for each procedure, the current risk assessment, and floor plans on display.', '', 8, '2026-10-25');
insert into public.compliance_guides (item_key, area, title, source_ref, summary, directions, evidence, retention, sort, checked_on) values
  ('premises', 'safety_premises', 'Premises and safety checks', 'National Regulations · Reg. 103–115',
   'Premises, furniture and equipment must be safe, clean and in good repair. The service also needs fencing, enough indoor and outdoor space, shade, toilets, nappy change areas, and a layout that lets educators supervise children.',
   array['Do a documented safety check of indoor and outdoor areas each day before children arrive.', 'Keep cleaning schedules for toys, equipment and areas children use.', 'Log repairs and maintenance, and follow manufacturers'' advice for equipment.', 'Check cots, mattresses and bedding meet Australian Standards, and make sure there are no bassinets on the premises (Reg. 84D).', 'Keep risk assessments of the physical environment, and a plan to protect children during any building work.']::text[],
   'Daily safety checklists, a maintenance log and cleaning schedules.', '', 9, '2026-10-25');
insert into public.compliance_guides (item_key, area, title, source_ref, summary, directions, evidence, retention, sort, checked_on) values
  ('emergency', 'safety_premises', 'Emergency contacts and procedures', 'National Regulations · Reg. 97, 173 · National Law s172',
   'Display the evacuation floor plan and instructions near each exit. Display the prescribed service information so it''s clearly visible from the main entrance, including approvals, the regulator''s contact details, the person in charge and who handles complaints.',
   array['Put the floor plan and evacuation instructions in a prominent position near each exit.', 'Display at the main entrance: provider and service approvals, your rating, the regulator''s contact details, the complaints contact, the nominated supervisor and the person in charge.', 'Where it applies, display a notice that an enrolled child is at risk of anaphylaxis (without naming them), and any infectious disease notice.', 'Update the display whenever the person in charge, nominated supervisor or contacts change. A display folder doesn''t count.', 'Keep each room''s emergency contact list up to date from the enrolment records.']::text[],
   'Photos of the entrance display and the floor plans at each exit, with dates.', '', 10, '2026-10-25');
insert into public.compliance_guides (item_key, area, title, source_ref, summary, directions, evidence, retention, sort, checked_on) values
  ('sun', 'policies_procedures', 'Sun Protection Policy reviewed and current', 'National Regulations · Reg. 114, 168 · NQS 2.2.1',
   'Centres must provide adequate shade outdoors and have health and safety policies. ACECQA''s sun protection guidelines recommend protection whenever the UV Index is 3 or above, using hats, clothing, sunscreen and shade, with educators modelling sun-safe behaviour.',
   array['Check the UV Index each day and use sun protection whenever it''s 3 or above.', 'Require sun-safe hats and clothing (for example "no hat, no play").', 'Keep enough in-date sunscreen. Babies 6 months and younger generally shouldn''t use sunscreen.', 'Check shade across the seasons, and include shade in excursion risk assessments.', 'Review the policy on a set schedule with a named person responsible. Tell families at least 14 days before changes that significantly affect them.']::text[],
   'The current sun protection policy with its review date.', '', 11, '2026-10-25');
insert into public.compliance_guides (item_key, area, title, source_ref, summary, directions, evidence, retention, sort, checked_on) values
  ('sleep', 'policies_procedures', 'Sleep and rest policy review', 'National Regulations · Reg. 84A–84D · NQS 2.1.1',
   'Meet each child''s sleep and rest needs. Base your sleep and rest policies on a risk assessment done at least every 12 months, and never have bassinets on the premises while children are in care.',
   array['Do a sleep and rest risk assessment at least every 12 months, and as soon as possible when something changes. Keep a record of each one. ACECQA has a template.', 'Update the policy after each assessment. Cover supervision (how often sleeping children are checked, and how that''s recorded), sleep areas, cots and bedding, hazards, temperature, lighting and ventilation.', 'Remove all bassinets from the premises.', 'Place babies under 12 months on their back, with head and face uncovered, on a firm, flat, well-fitting mattress in a safe cot.', 'Train staff on the policy and Red Nose safe sleep guidance, and share the policy with families.']::text[],
   'The latest risk assessment record, the policy with its review date, and sleep check records.', '', 12, '2026-10-25');
insert into public.compliance_guides (item_key, area, title, source_ref, summary, directions, evidence, retention, sort, checked_on) values
  ('excursions', 'safety_premises', 'Excursion risk assessments and authorisations', 'National Regulations · Reg. 100–102',
   'Do a risk assessment before every excursion, then get each family''s written authorisation before their child goes. A risk assessment for a regular outing stays valid for 12 months unless something changes.',
   array['Complete and record the risk assessment before asking families for authorisation. Cover the destination, travel and planned activities.', 'For a regular outing, check the risk assessment is less than 12 months old. Update it, and the authorisation forms, if the route, location or number of children changes.', 'Send families a written authorisation form explaining transport, how long it takes, the activities, and the risks and how you''ll manage them.', 'Have a written authorisation for every child before the day.', 'Plan ratios and groups around the risks, with a first-aid-qualified educator in each group.', 'Take the first aid kit, medication, medical management plans, emergency contacts and a phone. Do regular headcounts.']::text[],
   'A risk assessment for each excursion and regular outing, and signed authorisations for each child.', 'Child records, including authorisations: 3 years after the child''s last day at the service (Reg. 183).', 13, '2026-10-25');
insert into public.compliance_guides (item_key, area, title, source_ref, summary, directions, evidence, retention, sort, checked_on) values
  ('qip', 'policies_procedures', 'Quality Improvement Plan reviewed', 'National Regulations · Reg. 31, 55, 56',
   'Every service needs a Quality Improvement Plan: a self-assessment against the National Quality Standard, the areas you plan to improve, and your service philosophy. Review and revise it at least once a year, keep the current copy at the service, and give it to the regulator when asked.',
   array['Self-assess your practice against each of the 7 quality areas of the National Quality Standard, the National Law and the Regulations.', 'Record the areas that need improvement, with goals, steps, who''s responsible and a timeframe for each.', 'Keep the statement of philosophy in the plan current.', 'Review and revise the plan at least once a year, and whenever the regulator directs.', 'Keep the current plan at the service, where families and the regulator can see it.']::text[],
   'The current Quality Improvement Plan with its last review date.', '', 14, '2026-10-25');
